"""运行时配置 API。"""
import logging
import os
from fastapi import APIRouter, Request

logger = logging.getLogger('agent.server.config')

router = APIRouter(prefix='/config', tags=['config'])

# 允许通过 PUT /config 更新的字段白名单（安全考虑，避免任意注入敏感配置）
ALLOWED_CONFIG_KEYS = {
    # Codex 子 Agent
    'codex_enabled', 'codex_command', 'codex_model', 'codex_timeout',
    'codex_bypass_sandbox',
    # Qoder 子 Agent
    'qoder_enabled', 'qoder_command', 'qoder_timeout', 'qoder_yolo',
    # Claude Code 子 Agent
    'claude_code_enabled', 'claude_code_command', 'claude_code_model',
    'claude_code_timeout', 'claude_code_skip_permissions',
    # 其他非敏感运行参数
    'max_history', 'max_history_tokens', 'max_tool_rounds',
    'llm_timeout', 'tool_timeout', 'output_limit',
    'web_search_provider', 'web_search_timeout', 'web_search_backend',
    'summary_enabled', 'summary_token_threshold', 'summary_keep_recent',
}


@router.get('')
async def get_config():
    """获取运行时配置。"""
    from agent_runtime.server.app import get_agent_app
    app = get_agent_app()
    if not app:
        return {'error': 'Agent 未初始化'}
    cfg = app.config
    return {
        'agent_id': cfg.agent_id,
        'model_name': cfg.model_name,
        'fast_model_name': getattr(cfg, 'fast_model_name', ''),
        'llm_configured': cfg.llm_configured,
        'port': cfg.port,
        'home': str(cfg.home),
        'runtime_home': str(cfg.runtime_home),
        'workspace_dirs': cfg.workspace_dirs,
        'run_mode': getattr(cfg, 'run_mode', 'local'),
        'platform_enabled': os.environ.get('PLATFORM_WS_URL', '') != '',
        'codex': {
            'enabled': cfg.get('codex_enabled', False),
            'model': cfg.get('codex_model', 'gpt-5.4'),
            'command': cfg.get('codex_command', 'codex'),
        },
        'qoder': {
            'enabled': cfg.get('qoder_enabled', False),
            'command': cfg.get('qoder_command', 'qodercli'),
        },
        'claude_code': {
            'enabled': cfg.get('claude_code_enabled', False),
            'model': cfg.get('claude_code_model', 'claude-sonnet-4-20250514'),
            'command': cfg.get('claude_code_command', 'claude'),
            'timeout': cfg.get('claude_code_timeout', 600),
        },
    }


def _apply_provider_changes(app, updated: dict) -> None:
    """配置变更后热重建对应的子 Agent Provider。

    仅处理 codex/qoder/claude_code 三个 CLI 家族：
    - enabled 且 CLI 可用 → 重建并注册（同名覆盖）
    - 否则 → 注销
    """
    from agent_runtime.core.subagent import build_provider_by_name
    manager = getattr(app, 'subagent_manager', None)
    if manager is None:
        return
    params = app.config.params
    families = {
        'codex': ('codex_enabled', 'codex'),
        'qoder': ('qoder_enabled', 'qoder'),
        'claude_code': ('claude_code_enabled', 'claude-code'),
    }
    for prefix, (enabled_key, provider_name) in families.items():
        if not any(k.startswith(prefix) for k in updated):
            continue
        if params.get(enabled_key):
            provider = build_provider_by_name(provider_name, params)
            if provider is not None and provider._check_available():
                manager.register(provider)
                logger.info('配置变更：Provider 已重建注册 %s', provider_name)
        else:
            manager.unregister(provider_name)
            logger.info('配置变更：Provider 已注销 %s', provider_name)


@router.put('')
async def update_config(request: Request):
    """更新运行时配置并持久化到 config.json（仅白名单字段）。

    请求体为扁平 JSON 对象，如 {"codex_enabled": true, "codex_model": "..."}；
    兼容旧格式 {"key": "...", "value": "..."}。
    """
    from agent_runtime.server.app import get_agent_app
    app = get_agent_app()
    if not app:
        return {'success': False, 'error': 'Agent 未初始化'}
    config = app.config

    try:
        body = await request.json()
    except Exception:
        body = {}
    if not isinstance(body, dict):
        return {'success': False, 'error': '请求体必须为 JSON 对象'}

    # 兼容旧格式 {key, value}
    if set(body.keys()) == {'key', 'value'}:
        body = {body['key']: body['value']}

    updated = {}
    rejected = []
    for key, value in body.items():
        if key in ALLOWED_CONFIG_KEYS:
            config.params[key] = value
            updated[key] = value
        else:
            rejected.append(key)

    persisted = False
    if updated:
        persisted = config.save()
        try:
            _apply_provider_changes(app, updated)
        except Exception:
            logger.debug('应用 Provider 变更失败', exc_info=True)

    if rejected:
        logger.warning('PUT /config 拒绝了非白名单字段: %s', rejected)

    return {'success': True, 'status': 'ok', 'updated': updated,
            'rejected': rejected, 'persisted': persisted}
